bm-testimonial-44-grid.custom_css:
.bm-testimonial-44-grid {
  display: block !important;
  column-count: 3;
  row-gap: var(--row-gap);
  column-gap: var(--column-gap);
  --row-gap: var(--space-m);
  --column-gap: var(--space-m);

}

.bm-testimonial-44-grid > * {
  margin-block-end: var(--row-gap);
  break-inside: avoid;
  width: 100%;

}

@media (max-width: 768px) {
  .bm-testimonial-44-grid {
  column-count: 2;
}
}

@media (max-width: 478px) {
  .bm-testimonial-44-grid {
  column-count: 1;
}
}
